#!/usr/bin/env bash
set -e
echo "Adding a dev-only background sync debug panel to the Profile screen..."

echo "  screens/ProfileScreen.js"
mkdir -p "$(dirname 'screens/ProfileScreen.js')"
echo '' | base64 --decode > 'screens/ProfileScreen.js'

echo "Done. Open Profile in the app (dev build only) to see task status and a Run Sync Now button."
